#!/usr/bin/env python3
"""Exam theory questions -> data/theory.json."""
import json, os, sys
sys.argv = sys.argv[:1]
SRC = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(SRC)
exec(open(os.path.join(SRC, 'gen_cards.py')).read().split('C = []')[0])  # reuse fmt()
T = []
def q(ch, question, key):
    T.append({'id': f't{ch}-{sum(1 for t in T if t["ch"] == ch) + 1}', 'ch': ch, 'q': fmt(question), 'key': fmt(key)})

q('01', 'Опишите путь программы на C++ от исходного текста до исполняемого файла. Что делает каждый этап?',
  'Препроцессор обрабатывает директивы (`#include` вставляет текст заголовков, `#define` — макросы, условная компиляция), получается единица трансляции. Компилятор переводит её в объектный код (машинные инструкции + таблица символов), по одному объектному файлу на .cpp. Компоновщик объединяет объектные файлы и библиотеки, разрешает внешние символы (адреса функций/переменных из других файлов) и создаёт исполняемый файл. Ошибки: синтаксические/типов — на компиляции, «undefined reference» — на линковке.')
q('02', 'Фундаментальные типы C++: какие бывают, что гарантирует стандарт об их размерах, типичные размеры на 64-битной платформе.',
  'Целые (`short`, `int`, `long`, `long long`, знаковые/беззнаковые), символьные (`char`, `signed char`, `unsigned char` — три разных типа; `wchar_t`, `char8_t/16_t/32_t`), логический `bool`, вещественные (`float`, `double`, `long double`), `void`. Стандарт гарантирует `sizeof(char) == 1` и неубывание размеров short ≤ int ≤ long ≤ long long, минимальные ширины 16/16/32/64 бит. На LP64 (Linux x86-64): 1/2/4/8/8, float 4, double 8, указатель 8; на Windows `long` 4 байта.')
q('03', 'Переменные: объявление, определение, инициализация (виды), область видимости и время жизни. Что такое `auto`?',
  'Объявление вводит имя и тип, определение ещё и выделяет память; ODR — одно определение. Инициализация: копирующая `int a = 1;`, прямая `int a(1);`, унифицированная `int a{1};` (запрещает сужающие преобразования). Неинициализированные локальные — неопределённое значение (чтение — UB), глобальные/статические — нулём. Область видимости — блок `{}`, внутренний сосед скрывает внешнее имя. Время жизни: автоматическое (до конца блока), статическое (всю программу), динамическое (`new`/`delete`). `auto` выводит тип из инициализатора, отбрасывая ссылку и верхний `const`.')
q('04', 'Представление целых чисел: прямой, обратный и дополнительный код. Почему используется дополнительный? Что такое переполнение для знаковых и беззнаковых?',
  'Прямой: старший бит — знак, остальное модуль; два нуля. Обратный: отрицательное — инверсия битов; тоже два нуля. Дополнительный: −x = ~x + 1; один ноль, диапазон −2ⁿ⁻¹..2ⁿ⁻¹−1, сложение и вычитание выполняются одной схемой для знаковых и беззнаковых — поэтому он используется (с C++20 закреплён стандартом). Беззнаковые считаются по модулю 2ⁿ — переполнения в смысле UB нет. Переполнение знаковых — UB: компилятор вправе считать его невозможным. Смешение знаковых и беззнаковых в выражении приводит к беззнаковому (`-1 < 0u` ложно).')
q('05', 'Побитовые операции C++. Приведите примеры битовых трюков и объясните, почему они работают.',
  'Операции: `&`, `|`, `^`, `~`, `<<`, `>>`. Проверка бита `(x >> k) & 1`, установка `x | (1 << k)`, сброс `x & ~(1 << k)`, инверсия `x ^ (1 << k)`. `x & (x - 1)` сбрасывает младшую единицу → проверка степени двойки и подсчёт битов (Керниган). XOR: `a ^ a = 0`, `a ^ 0 = a` → поиск непарного элемента, обмен без временной переменной. `x & -x` — младшая единица. `<<` на k — умножение на 2ᵏ. UB: сдвиг на отрицательное или ≥ ширины типа. `>>` для отрицательных — арифметический (гарантирован с C++20).')
q('06', 'Стандарт IEEE 754: устройство float/double, специальные значения, потеря точности и неассоциативность сложения.',
  'Число = (−1)^знак · 1.мантисса · 2^(экспонента − смещение). float: 1+8+23 бит, смещение 127, ~7 значащих цифр; double: 1+11+52, смещение 1023, ~15–16 цифр. Экспонента из единиц: ±inf (мантисса 0) и NaN; из нулей: ±0 и денормализованные числа. Многие десятичные дроби (0.1) не представимы точно → `0.1 + 0.2 != 0.3`, сравнивать с eps. Потеря значимости: при сложении чисел разного порядка младшее теряется (`1e8f + 1 == 1e8f`). Каждая операция округляет, поэтому `(a+b)+c ≠ a+(b+c)`; суммировать лучше от малых к большим (или Кэхэн).')
q('07', 'Что такое неопределённое поведение (UB)? Приведите примеры из курса и объясните, почему компилятор «ломает» программы с UB.',
  'UB — поведение, на которое стандарт не накладывает требований: может произойти что угодно, включая «работает». Примеры: переполнение знаковых, чтение неинициализированной переменной, выход за границу массива, разыменование nullptr/висячего указателя, двойной delete, сдвиг на ≥ ширины типа, модификация строкового литерала, деление целого на ноль. Оптимизатор исходит из того, что UB не бывает: `x + 1 > x` для `int` заменяет на `true`, удаляет «невозможные» проверки и ветки. Защита: `-Wall -Wextra`, санитайзеры (`-fsanitize=address,undefined`), проверка условий до операции.')
q('08', 'Условные конструкции C++: `?:`, `if`, `switch`. Особенности и типичные ошибки.',
  '`?:` — выражение, возвращает значение (может быть lvalue), оба операнда приводятся к общему типу. `if/else` — оператор; условие преобразуется к bool; `if (init; cond)` с C++17; ошибка `if (x = 5)`; «висячий else» относится к ближайшему `if`. `switch` — по целочисленному/перечисляемому выражению, метки `case` — константы; без `break` выполнение «проваливается» дальше (`[[fallthrough]]` для намеренного), `default` — остальные случаи; нельзя перепрыгнуть инициализацию переменной — нужен блок `{}`.')
q('09', 'Циклы в C++: виды, отличия, управляющие операторы. Типичные ошибки.',
  '`while` — проверка до тела (может не выполниться ни разу), `do-while` — после (хотя бы раз), `for (init; cond; step)` — удобен для счётчиков, переменная из init видна только в цикле, range-based `for (auto& x : c)`. `break` — выход из ближайшего цикла/switch, `continue` — к следующей итерации (в for сначала step). Ошибки: бесконечный цикл с `unsigned i >= 0`, выход за границу `i <= n`, сравнение вещественных счётчиков на равенство, изменение контейнера во время обхода.')
q('10', 'Функции: объявление и определение, способы передачи параметров, значения по умолчанию, перегрузка и правила её разрешения.',
  'Объявление (прототип) — сигнатура без тела, определение — с телом. Передача по значению (копия), по указателю (можно менять объект, может быть nullptr), по ссылке (псевдоним), по `const&` (без копий и изменений). Значения по умолчанию — только справа налево, задаются один раз. Перегрузка — одно имя, разные списки параметров (возвращаемый тип не учитывается). Разрешение: точное совпадение (включая тривиальные преобразования) → продвижение (char/short→int, float→double) → стандартные преобразования (int→double, int→long, double→int) → пользовательские. Несколько одинаково хороших — ошибка неоднозначности.')
q('10', 'Рекурсия и статические локальные переменные. Как рекурсия связана со стеком вызовов? Приведите пример.',
  'Рекурсивная функция вызывает сама себя; нужен базовый случай и шаг к нему. Каждый вызов получает свой кадр стека (параметры, локальные переменные, адрес возврата), поэтому глубина ограничена размером стека (иначе stack overflow). Пример: факториал `n <= 1 ? 1 : n * fact(n - 1)`, Ханойские башни (2ⁿ − 1 ходов). Наивный Фибоначчи экспоненциален из-за повторных вычислений. Статическая локальная переменная инициализируется один раз и хранится в data/bss, а не в кадре — общая для всех вызовов (например, счётчик вызовов).')
q('12', 'Сегменты памяти процесса. Где хранятся код, глобальные, статические, локальные и динамические объекты?',
  'text — машинный код (только чтение/исполнение); rodata — константы и строковые литералы; data — инициализированные ненулём глобальные и статические переменные; bss — нулевые/неинициализированные глобальные и статические (обнуляются при запуске); heap — динамическая память (`new`/`delete`), растёт вверх; stack — кадры вызовов: локальные переменные, параметры, адреса возврата, растёт вниз, мал (мегабайты). Время жизни: статическое — всю программу, автоматическое — до конца блока, динамическое — до `delete`.')
q('13', 'Указатели: определение, операции, арифметика указателей, связь с const, нулевой и void-указатели.',
  '`T* p` хранит адрес объекта типа T; `&x` — адрес, `*p` — разыменование. Арифметика: `p + n` сдвигает на n·sizeof(T) байт, разность указателей — число элементов (только внутри одного массива), сравнение `<` осмысленно в одном массиве. const: `const T* p` — нельзя менять объект через p, `T* const p` — нельзя менять сам p. `nullptr` — нулевой указатель (тип nullptr_t), разыменование — UB. `void*` хранит любой адрес, но не разыменовывается и не участвует в арифметике — нужен `static_cast`. Указатель на указатель `T**` — для изменения указателя в функции и динамических матриц.')
q('13', 'Динамическое выделение памяти: `new`/`delete`, `new[]`/`delete[]`. Перечислите типичные ошибки и их последствия.',
  '`new T(args)` выделяет память в куче и вызывает конструктор, возвращает указатель; `delete p` вызывает деструктор и освобождает. Для массивов — `new T[n]` и строго `delete[]`. Ошибки: утечка памяти (потерян указатель без delete), висячий указатель (использование после delete) — UB, двойное освобождение — UB, несоответствие `delete`/`delete[]` — UB, возврат адреса локальной переменной. `delete nullptr` безопасен. Решение — RAII и умные указатели (`std::unique_ptr`, `std::vector`).')
q('14', 'Ссылки: что это, чем отличаются от указателей, когда что использовать. Передача параметров по ссылке.',
  'Ссылка — псевдоним существующего объекта: обязательно инициализируется, не перепривязывается, не бывает нулевой, нет арифметики, `sizeof` ссылки — размер объекта. Указатель — отдельный объект с адресом, может быть nullptr и перенаправляться. По ссылке передают, когда функция должна изменить аргумент (`swap(int&, int&)`) или чтобы избежать копирования (`const T&`). `const T&` может привязаться к временному объекту (продление жизни). Нельзя возвращать ссылку на локальную переменную — висячая ссылка.')
q('15', 'Умные указатели: unique_ptr, shared_ptr, weak_ptr. Семантика владения, примеры использования, циклические ссылки.',
  '`unique_ptr` — единоличное владение, удаляет объект в деструкторе, некопируемый, перемещаемый (`std::move`), создаётся `make_unique`. `shared_ptr` — совместное владение со счётчиком ссылок в control block: копия +1, уничтожение −1, при 0 удаляет объект; `make_shared` — одно выделение. `weak_ptr` — невладеющее наблюдение за shared_ptr, не меняет счётчик; `lock()` даёт shared_ptr или пустой, `expired()`. Цикл shared_ptr (A↔B) никогда не обнулит счётчики → утечка; одну из связей делают weak_ptr.')
q('16', 'Массивы в C++: статические и динамические, связь с указателями, передача в функцию, основные правила работы.',
  'Статический массив `T a[N]` — N подряд идущих элементов, N — константа времени компиляции, размер `sizeof(a)/sizeof(a[0])`. Имя массива в выражениях распадается в указатель на первый элемент; `a[i] ≡ *(a + i)`. При передаче в функцию `T a[]` — это `T*`, размер теряется, его передают отдельно. Массивы не присваиваются и не сравниваются целиком. Выход за границы — UB. Динамический: `new T[n]` (n в рантайме), освобождение `delete[]`; размер нужно хранить самому; изменение размера — выделить новый, скопировать, удалить старый.')
q('17', 'Строки: C-строки и std::string, основные методы std::string, std::string_view. Изменяемость строк.',
  'C-строка — массив char с терминальным `\'\\0\'`; длина `strlen` за O(n); функции `<cstring>` (strcpy, strcmp) опасны переполнением буфера. Строковый литерал — `const char[N]`, менять нельзя. `std::string` владеет памятью, хранит длину, поддерживает `+`, сравнения, `size`, `find` (npos при неудаче), `substr`, `insert`, `erase`, `replace`, `c_str()`, `at` с проверкой. `std::string_view` (C++17) — невладеющий указатель+длина, дешёвый параметр «только чтение»; опасен, если переживает исходную строку.')
q('18', 'Работа с файлами в C++: потоки, режимы открытия, чтение и запись, проверка ошибок.',
  '`<fstream>`: `ifstream` — чтение, `ofstream` — запись, `fstream` — оба. Открытие конструктором или `open`; проверка `is_open()` / `if (!f)`. Режимы: `ios::in`, `ios::out`, `ios::app` (дописывать), `ios::trunc` (очистить), `ios::binary`. Чтение: `f >> x` (до пробела), `std::getline(f, line)`; правильный цикл — `while (getline(f, line))`, а не `while (!eof())`. Запись — `<<`. Закрытие автоматически в деструкторе (RAII) или `close()`. `std::stringstream` — разбор строки как потока.')
q('19', 'Многомерные массивы: статические и динамические, расположение в памяти, способы выделения и освобождения.',
  '`int a[R][C]` — один непрерывный блок по строкам (row-major), `a[i][j]` по смещению `i*C + j`; в функцию передаётся как `int a[][C]` (все размеры кроме первого известны). Динамические: массив указателей `int** a = new int*[R]` + каждая строка `new int[C]`, освобождение в обратном порядке (`delete[] a[i]`, затем `delete[] a`); допускает «рваные» строки. Альтернатива — один блок `new int[R*C]` с индексом `i*C + j`: одно выделение, лучше кеш. Обход по строкам быстрее обхода по столбцам из-за локальности.')
q('20', 'Структуры: объявление, инициализация, статические поля, размер и выравнивание.',
  '`struct` группирует поля разных типов; доступ `.`, через указатель `->`. Инициализация агрегатная `{...}`, назначенные инициализаторы (C++20), значения полей по умолчанию. Статическое поле одно на тип, не входит в sizeof, определяется вне структуры или `inline static`. Выравнивание: поле располагается по адресу, кратному его alignof; компилятор добавляет padding между полями и в конце, sizeof кратен максимальному выравниванию. Пример `{char; int; char}` = 12, а `{int; char; char}` = 8. `#pragma pack` убирает выравнивание ценой скорости.')
q('21', 'Парадигмы программирования. Принципы ООП с примерами на C++.',
  'Парадигма — набор идей и приёмов организации программ: императивная/процедурная (последовательность команд, функции), структурная (последовательность, ветвление, цикл без goto), ООП (объекты = данные + поведение), функциональная (чистые функции, неизменяемость), обобщённая (шаблоны). ООП: инкапсуляция — объединение данных и методов и сокрытие реализации (`private` поля, публичный интерфейс); наследование — новый класс на основе существующего; полиморфизм — один интерфейс, разные реализации (перегрузка, виртуальные функции); абстракция — выделение существенного.')
q('22', 'Классы и объекты: модификаторы доступа, методы, `this`, константные и статические методы.',
  'Класс — пользовательский тип с полями и методами; объект — экземпляр. `public`/`private`/`protected`; в `class` по умолчанию private, в `struct` public. Методы могут быть определены в классе (неявно inline) или вне через `Class::method`. `this` — указатель на текущий объект. Константный метод `f() const` не меняет объект и вызывается у константных объектов; `mutable` поля можно менять и в нём (логическая vs физическая константность). Статические методы и поля принадлежат классу: нет `this`, вызов `Class::f()`.')
q('23', 'Конструкторы: виды, списки инициализации, explicit, конструктор по умолчанию и копирования, делегирование.',
  'Конструктор — метод с именем класса без возвращаемого типа, вызывается при создании. Виды: по умолчанию (без аргументов; генерируется, если нет других; `= default`), параметрический, копирования `T(const T&)` (параметр по ссылке, иначе бесконечная рекурсия; генерируемый копирует поля поверхностно), преобразования (с одним параметром — неявное приведение; `explicit` его запрещает), делегирующий (`T() : T(0) {}`). Список инициализации инициализирует поля до тела; обязателен для const, ссылок, полей без конструктора по умолчанию; порядок — порядок объявления полей. `T x();` — объявление функции (most vexing parse).')
q('24', 'Деструктор: когда вызывается, правила, что в нём делать. Порядок вызова конструкторов и деструкторов.',
  'Деструктор `~T()` — один, без параметров, вызывается автоматически в конце жизни объекта: выход из блока, `delete`, завершение программы для статических. Освобождает ресурсы, которыми владеет объект (память, файлы, блокировки); не должен бросать исключения. Явно вызывать почти никогда не нужно. Локальные объекты уничтожаются в обратном порядке создания; поля — в обратном порядке объявления, после тела деструктора класса; конструирование полей идёт в прямом порядке до тела конструктора.')
q('25', 'Идиома RAII и правило трёх. Что произойдёт, если правило трёх нарушить? Покажите на примере класса с динамическим массивом.',
  'RAII: время жизни ресурса привязано к времени жизни объекта — захват в конструкторе, освобождение в деструкторе; ресурс освобождается при любом выходе из области видимости. Правило трёх: если нужен пользовательский деструктор, конструктор копирования или оператор присваивания — нужны все три. Класс с `int* data_` и деструктором `delete[] data_`, но без копирования: генерируемое копирование скопирует указатель → два объекта делят буфер, изменения видны обоим, при разрушении — двойной delete (UB); присваивание вдобавок теряет старый буфер (утечка). Решения: глубокое копирование, copy-and-swap, `= delete` для некопируемых, правило нуля (std::vector / unique_ptr).')
q('26', 'Перегрузка операций: синтаксис, ограничения, метод или внешняя функция. Особенности `++`, `[]`, `=`, `<<`.',
  'Оператор — функция `operator@`. Нельзя перегрузить `::`, `.`, `.*`, `?:`, `sizeof`; нельзя создать новые операторы, менять приоритет и арность; хотя бы один операнд — пользовательский тип. Только методами: `=`, `[]`, `()`, `->`. Симметричные бинарные (`+`, `==`) лучше внешними — работает преобразование левого операнда; доступ к private — через геттеры или `friend`. Префиксный `T& operator++()`, постфиксный `T operator++(int)` возвращает старую копию. `[]` — две версии (const и не const). `operator=` возвращает `T&` на `*this`, обрабатывает самоприсваивание. `operator<<(std::ostream&, const T&)` — внешний, возвращает поток для цепочек.')
